import{_ as t,o as r,c as s,a5 as a}from"./chunks/framework.CslsFoWx.js";const n="/VendoraSystem-docs/captures/2026-11-09-textes-serveur-restants/web-avant-en-01-serveur-injoignable.webp",o="/VendoraSystem-docs/captures/2026-11-09-textes-serveur-restants/web-apres-en-01-serveur-injoignable.webp",d="/VendoraSystem-docs/captures/2026-11-09-textes-serveur-restants/web-avant-ar-01-serveur-injoignable.webp",i="/VendoraSystem-docs/captures/2026-11-09-textes-serveur-restants/web-apres-ar-01-serveur-injoignable.webp",c="/VendoraSystem-docs/captures/2026-11-09-textes-serveur-restants/ios-avant-en-01-file-impression.webp",u="/VendoraSystem-docs/captures/2026-11-09-textes-serveur-restants/ios-apres-en-01-file-impression.webp",l="/VendoraSystem-docs/captures/2026-11-09-textes-serveur-restants/ios-avant-ar-01-file-impression.webp",p="/VendoraSystem-docs/captures/2026-11-09-textes-serveur-restants/ios-apres-ar-01-file-impression.webp",m="/VendoraSystem-docs/captures/2026-11-09-textes-serveur-restants/ios-avant-en-02-alertes.webp",g="/VendoraSystem-docs/captures/2026-11-09-textes-serveur-restants/ios-apres-en-02-alertes.webp",v="/VendoraSystem-docs/captures/2026-11-09-textes-serveur-restants/ios-avant-ar-02-alertes.webp",b="/VendoraSystem-docs/captures/2026-11-09-textes-serveur-restants/ios-apres-ar-02-alertes.webp",h="/VendoraSystem-docs/captures/2026-11-09-textes-serveur-restants/ios-avant-en-03-ecran-cuisine.webp",f="/VendoraSystem-docs/captures/2026-11-09-textes-serveur-restants/ios-apres-en-03-ecran-cuisine.webp",x="/VendoraSystem-docs/captures/2026-11-09-textes-serveur-restants/ios-avant-ar-03-ecran-cuisine.webp",A="/VendoraSystem-docs/captures/2026-11-09-textes-serveur-restants/ios-apres-ar-03-ecran-cuisine.webp",w=JSON.parse('{"title":"Textes du serveur restants et badges DEV / STAGING (carte Trello P3, 09/11/2026)","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-11-09-textes-serveur-restants.md","filePath":"generated/preuves/2026-11-09-textes-serveur-restants.md","lastUpdated":null}'),S={name:"preuves/2026-11-09-textes-serveur-restants.md"};function q(T,e,_,k,P,V){return r(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="textes-du-serveur-restants-et-badges-dev-staging-carte-trello-p3-09-11-2026" tabindex="-1">Textes du serveur restants et badges DEV / STAGING (carte Trello P3, 09/11/2026) <a class="header-anchor" href="#textes-du-serveur-restants-et-badges-dev-staging-carte-trello-p3-09-11-2026" aria-label="Permalink to &quot;Textes du serveur restants et badges DEV / STAGING (carte Trello P3, 09/11/2026)&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-11-09-textes-serveur-restants</code> · 0 image(s) · 0 trace(s)</p><div><p>Objectif : un commerçant qui utilise le back-office ou la caisse en anglais ou en arabe ne voit plus de texte en français venu du serveur, du moteur partagé ou du transport, ni d&#39;erreur technique brute.</p><h2 id="point-reel-inventaire-du-09-11" tabindex="-1">Point réel (inventaire du 09/11) <a class="header-anchor" href="#point-reel-inventaire-du-09-11" aria-label="Permalink to &quot;Point réel (inventaire du 09/11)&quot;">​</a></h2><p>Après la carte du 08/11 (≈ 450 messages du serveur traduits au back-office) et les restes du 09/11 (paiement « Autre », motifs de remise, travaux d&#39;impression « Ticket No »), une relecture des sources des deux apps a trouvé :</p><table tabindex="0"><thead><tr><th>Reste</th><th>Où</th><th>Avant</th><th>Après</th></tr></thead><tbody><tr><td>Erreur brute du transport d&#39;impression (« Failed to connect to InetSocketAddress(…) », « Timeout après 3000 ms vers … », « Bluetooth désactivé », « Imprimante simulée : … », « Liaison USB non disponible… »)</td><td>file d&#39;impression, test d&#39;impression, diagnostic (iOS et Android)</td><td>affichée telle quelle</td><td><code>printErrorLabel</code> : « Printer unreachable (connection refused or network down) », « No response from the printer (3000 ms) »… ; un message inconnu (pilote) reste tel quel</td></tr><tr><td>Noms des travaux : « Page de test », « Bon cuisine · Table 5 · … · réimpression », « Pré-addition · … »</td><td>file d&#39;impression</td><td>en français</td><td><code>printJobLabel</code> étendu</td></tr><tr><td><strong>Android</strong> : file d&#39;impression entièrement en français (titre, statut « Nouvel essai (3 échec(s)) », « redirigé depuis », « Imprimante de caisse »)</td><td><code>PrintQueueScreen</code></td><td>français</td><td>mêmes textes que l&#39;iOS (<code>jobStatus</code>, <code>jobKind</code>, <code>redirectedFrom</code>, <code>receiptPrinter</code>)</td></tr><tr><td><strong>Android</strong> : libellés du kiosque « Kiosque A12 · 7 » ≠ iOS « Kiosque · A12 · Ticket No 7 »</td><td><code>KioskTicketPrinting</code></td><td>non reconnus à la traduction</td><td>format iOS (parité)</td></tr><tr><td>Alerte d&#39;imprimante de l&#39;écran cuisine (« Imprimante Cuisine chaude sans papier (…) — 3 bon(s) en attente à la caisse »)</td><td>écran cuisine iOS / Android</td><td>en français dans toutes les langues</td><td><code>kitchenPrintAlertText</code></td></tr><tr><td>Événements rejetés par le serveur (« Rejeté : contenu illisible — Contenu de … illisible »)</td><td>feuille « Événements rejetés »</td><td>en français</td><td><code>rejectedEventLabel</code> (motif traduit ; détail du serveur reconnu traduit, détail inconnu omis hors français)</td></tr><tr><td>Paiements fournisseur : « Réseau indisponible », erreur réseau brute, « Lien Konnect expiré », « Délai dépassé », « Erreur 503 »…</td><td>paiement QR / lien / TPE, repli du remboursement</td><td>brut ou français</td><td><code>providerMessage</code> ; le client n&#39;envoie plus l&#39;erreur brute du système mais « Réseau indisponible » (protocole) traduit à l&#39;écran</td></tr><tr><td>Alertes des responsables : titres et résumés rédigés en français par le serveur (anti-fraude, écart de caisse, transfert, stock bas, péremption, e-reporting) et suite (« Acquittée par … »)</td><td>écran « Alertes » et notifications (iOS et Android)</td><td>en français</td><td><code>managerAlertTitle</code> / <code>managerAlertBody</code> / <code>managerAlertResolution</code> (gabarits ; données du commerce gardées)</td></tr><tr><td><strong>Android</strong> : statut d&#39;alerte « À traiter », avis « prêt » de la salle (« Table 5 — Envoi 2 prêt (…) »), « 58 mm (32 colonnes) », « … produit(s) » des transferts</td><td>Android</td><td>français</td><td>textes déjà traduits utilisés par l&#39;iOS (parité)</td></tr><tr><td><strong>Android</strong> : démo moteur (« Caisse — démo moteur », « TVA ventilée », « Démo catalogue 50 000 produits », bannière du catalogue de référence) atteignable par <strong>« Mode démo sans serveur » en production</strong></td><td><code>RegisterDemoScreen</code>, <code>PerfDemoHome</code></td><td>français</td><td>traduits (<code>CaisseRemoteTexts.demo*</code>) ; page d&#39;aide EN / AR mise à jour</td></tr><tr><td>Back-office : serveur injoignable (« Failed to fetch », « Erreur 0 »), corps d&#39;erreur par défaut de Spring (« Internal Server Error », « Not Found »), page HTML 502 / 503 / 504 d&#39;un relais</td><td>toutes les pages</td><td>brut</td><td>intercepteur : « Server unreachable: check the network connection, then try again. », « Server error (500). Try again; if the problem persists, contact support. »</td></tr></tbody></table><h3 id="restent-en-francais-volontairement-verifie" tabindex="-1">Restent en français, volontairement (vérifié) <a class="header-anchor" href="#restent-en-francais-volontairement-verifie" aria-label="Permalink to &quot;Restent en français, volontairement (vérifié)&quot;">​</a></h3><ul><li><strong>Écrans de développement</strong> des caisses (catalogue de composants, démo moteur iOS, performance) : atteignables seulement dans le <strong>build debug</strong> (<code>BuildConfig.DEBUG</code> sur Android, <code>#if DEBUG</code> sur iOS, décision D9). Les builds staging et prod dérivent de <code>release</code> (<code>initWith(release)</code>, configuration Xcode « Staging » de type release) : ils ne les montrent pas.</li><li><strong>Rapport du diagnostic matériel</strong> copié : protocole de <code>VALIDATION-MATERIEL.md</code>, lu par l&#39;équipe, toujours en français et de gauche à droite (l&#39;écran du diagnostic, lui, est traduit).</li><li><strong>Console Vendora</strong> : outil interne de l&#39;équipe Vendora, sans i18n.</li><li>Ce qui est <strong>stocké, envoyé au serveur ou imprimé</strong> (noms de travaux, <code>lastError</code>, alertes stockées, tickets) : protocole en français, traduit à l&#39;affichage seulement.</li></ul><h3 id="badges-d-environnement-«-dev-»-«-staging-»-—-decision" tabindex="-1">Badges d&#39;environnement « DEV » / « STAGING » — décision <a class="header-anchor" href="#badges-d-environnement-«-dev-»-«-staging-»-—-decision" aria-label="Permalink to &quot;Badges d&#39;environnement « DEV » / « STAGING » — décision&quot;">​</a></h3><p>Les <strong>sigles restent tels quels</strong> à l&#39;écran dans les trois langues : ce sont des repères techniques communs à l&#39;équipe et au support (« tu es sur la STAGING ? »), jamais visibles d&#39;un commerçant en production (<code>badgeLabel</code> vaut <code>null</code> en prod). Ce qui manquait, c&#39;est la <strong>lecture d&#39;écran</strong> : TalkBack et VoiceOver disaient « D E V ». Le badge annonce maintenant « Version de développement » / « Development build » / « نسخة التطوير » (et « Version de recette (staging) » / « Staging build » / « نسخة الاختبار (staging) ») — <code>CaisseRemoteTexts.envDevA11y</code> / <code>envStagingA11y</code>, parité iOS / Android. Décision réversible : remplacer le sigle par ces textes ne demande qu&#39;une ligne par app.</p><h2 id="garde-fous-echouent-sur-tout-nouveau-texte-non-traduit" tabindex="-1">Garde-fous (échouent sur tout nouveau texte non traduit) <a class="header-anchor" href="#garde-fous-echouent-sur-tout-nouveau-texte-non-traduit" aria-label="Permalink to &quot;Garde-fous (échouent sur tout nouveau texte non traduit)&quot;">​</a></h2><ul><li><code>shared/…/i18n/TextesServeurRestants0911Test.kt</code> (8 tests) : chaque texte connu (<code>FRENCH_SAMPLES</code>, 46 exemples) sort en anglais sans signe du français et en arabe avec des lettres arabes, et reste identique en français (le gabarit reconnaît bien le texte stocké).</li><li><code>androidApp/…/i18n/TextesEnDurCouvertureTest.kt</code> (3 tests) relit les sources <strong>Android et iOS</strong> : aucun texte français en dur passé à un composant affiché (<code>Text(&quot;…&quot;)</code>, <code>Button(&quot;…&quot;)</code>, <code>contentDescription</code>, <code>PosBanner(texte:)</code>…) hors écrans debug ; aucun texte stocké en français affiché sans sa fonction de traduction (<code>lastError</code>, <code>statusLabel</code>, <code>kind.label</code>, alertes, événements rejetés, paiements fournisseur…).</li><li><code>web/…/i18n-coverage.spec.ts</code> : relit aussi les corps d&#39;erreur composés à la main par le serveur (<code>mapOf(&quot;error&quot; to &quot;…&quot;)</code>, <code>&quot;message&quot; to &quot;…&quot;</code>) ; <code>server-messages.spec.ts</code> : statut 0, corps Spring, page 502.</li></ul><h2 id="captures" tabindex="-1">Captures <a class="header-anchor" href="#captures" aria-label="Permalink to &quot;Captures&quot;">​</a></h2><h3 id="back-office-avant-depot-principal-4200-apres-ce-lot-4293-meme-serveur-de-dev" tabindex="-1">Back-office (avant : dépôt principal <code>:4200</code> ; après : ce lot <code>:4293</code>, même serveur de dev) <a class="header-anchor" href="#back-office-avant-depot-principal-4200-apres-ce-lot-4293-meme-serveur-de-dev" aria-label="Permalink to &quot;Back-office (avant : dépôt principal `:4200` ; après : ce lot `:4293`, même serveur de dev)&quot;">​</a></h3><p>Coupure réseau <strong>simulée</strong> dans la page (les appels <code>/api/</code> partent vers un port fermé, statut 0 comme un poste qui perd sa connexion), puis « Last 30 days » sur la page Anti-fraude du commerce « Le Petit Bistrot (démo) ». Scénario : <code>capture.mjs</code> (scénario dans le rapport du lot).</p><table tabindex="0"><thead><tr><th>Avant</th><th>Après</th><th>Ce que montre la capture</th></tr></thead><tbody><tr><td><img src="'+n+'" alt=""></td><td><img src="'+o+'" alt=""></td><td>(1) Avant : « Failed to fetch », message brut du navigateur. Après : « Server unreachable: check the network connection, then try again. »</td></tr><tr><td><img src="'+d+'" alt=""></td><td><img src="'+i+'" alt=""></td><td>(1) La même page en arabe : « Failed to fetch » en anglais au milieu d&#39;une page arabe, puis « تعذّر الوصول إلى الخادم: تحقّق من الاتصال بالشبكة ثم أعد المحاولة. »</td></tr></tbody></table><p>Scénario <code>capture.mjs</code> utilisé (compte de démo du fichier de secrets, hors dépôt) : <code>aller /fraud</code>, <code>js</code> qui redirige <code>fetch</code> / <code>XMLHttpRequest</code> des URL <code>/api/</code> vers <code>http://127.0.0.1:9</code>, <code>cliquer button[aria-pressed=false]</code>, <code>attendre .vd-banner.danger</code>, <code>annoter</code>, <code>capture</code> ; <code>--langue en|ar</code>, <code>--web http://localhost:4200</code> (avant) ou <code>:4293</code> (après).</p><h3 id="app-ios-simulateur-iphone-16-dedie-mode-demo-barre-d-etat-09-41" tabindex="-1">App iOS (simulateur iPhone 16 dédié, mode démo, barre d&#39;état 09:41) <a class="header-anchor" href="#app-ios-simulateur-iphone-16-dedie-mode-demo-barre-d-etat-09-41" aria-label="Permalink to &quot;App iOS (simulateur iPhone 16 dédié, mode démo, barre d&#39;état 09:41)&quot;">​</a></h3><p>« Avant » : l&#39;app du commit de départ du lot (<code>b0b28f49</code>) avec SEULEMENT les nouvelles étapes de capture ajoutées (mêmes données semées) ; « après » : ce lot. Commande : <code>xcrun simctl launch &amp;lt;udid&gt; tn.pos.app -device.role caisse|cuisine -demo.capture &amp;lt;étape&gt; -demo.locale en|ar</code>.</p><table tabindex="0"><thead><tr><th>Étape</th><th>Avant</th><th>Après</th><th>Ce que montre la capture</th></tr></thead><tbody><tr><td><code>file-impression-liste</code> (en)</td><td><img src="'+c+'" alt=""></td><td><img src="'+u+'" alt=""></td><td>Ticket de test resté en file (imprimante 192.168.1.50 injoignable). Avant : « Page de test » et l&#39;erreur brute du transport (« Failed to connect to InetSocketAddress(…) » ou « Timeout après 3000 ms vers … »). Après : « Test page » et « Printer unreachable (…) » / « No response from the printer (3000 ms) ».</td></tr><tr><td><code>file-impression-liste</code> (ar)</td><td><img src="'+l+'" alt=""></td><td><img src="'+p+'" alt=""></td><td>La même file en arabe : « صفحة اختبار » et l&#39;erreur dans la langue de l&#39;écran.</td></tr><tr><td><code>alertes-serveur</code> (en)</td><td><img src="'+m+'" alt=""></td><td><img src="'+g+'" alt=""></td><td>Écran « Alerts » avec des alertes telles que stockées. Avant : titres et résumés en français (« Alerte anti-fraude : Remises fréquentes », « Karim : 7 remises le … — 7 preuve(s) », « Transfert à réceptionner »…). Après : « Fraud alert: Frequent discounts », « Karim: 7 discounts on 09/11/2026 (threshold 5/day) — 7 piece(s) of evidence », « Transfer to receive »… Les noms (Karim, Croissant, Comptoir 1, « erreur de rendu ») sont des données du commerce, non traduites.</td></tr><tr><td><code>alertes-serveur</code> (ar)</td><td><img src="'+v+'" alt=""></td><td><img src="'+b+'" alt=""></td><td>Les mêmes alertes en arabe ; noms, nombres et dates isolés (U+2068 … U+2069) pour garder l&#39;ordre de la phrase de droite à gauche.</td></tr><tr><td><code>ux-kds</code>, rôle cuisine (en)</td><td><img src="'+h+'" alt=""></td><td><img src="'+f+'" alt=""></td><td>Bandeau d&#39;imprimante cuisine. Avant : « Imprimante Cuisine chaude sans papier (192.168.1.51) — 3 bon(s) en attente à la caisse. Follow the tickets on this screen. » (moitié français). Après : « Printer Cuisine chaude out of paper (192.168.1.51) — 3 ticket(s) waiting at the register. … »</td></tr><tr><td><code>ux-kds</code>, rôle cuisine (ar)</td><td><img src="'+x+'" alt=""></td><td><img src="'+A+'" alt=""></td><td>Le même bandeau en arabe. L&#39;en-tête serré de l&#39;écran cuisine sur iPhone est connu (cible tablette, spec 09) et sans rapport avec ce lot.</td></tr></tbody></table><h3 id="android-pas-d-emulateur-supplementaire-scenes-a-capturer-par-l-integrateur-sur-emulator-5554" tabindex="-1">Android (pas d&#39;émulateur supplémentaire : scènes à capturer par l&#39;intégrateur sur emulator-5554) <a class="header-anchor" href="#android-pas-d-emulateur-supplementaire-scenes-a-capturer-par-l-integrateur-sur-emulator-5554" aria-label="Permalink to &quot;Android (pas d&#39;émulateur supplémentaire : scènes à capturer par l&#39;intégrateur sur emulator-5554)&quot;">​</a></h3><p>Les mêmes textes passent par les mêmes fonctions partagées (tests JVM <code>TextesServeurRestants0911Test</code>, garde-fou <code>TextesEnDurCouvertureTest</code>). Scènes à capturer, langue de l&#39;appareil en anglais puis en arabe :</p><ol><li><strong>File d&#39;impression</strong> : imprimante réseau <code>192.168.1.50:9100</code> (injoignable), « Imprimer un ticket de test », puis menu ⋮ → Réglages imprimante → « File d&#39;impression ». Attendu : « Test page », « Retrying (n failure(s)) — Printer unreachable (…) » ou « No response from the printer (3000 ms) », « Network · 192.168.1.50:9100 » (avant : tout en français : « Page de test », « Nouvel essai (1 échec(s)) — failed to connect… »).</li><li><strong>Mode démo sans serveur → Caisse</strong> : « Register — engine demo », « Cart », « VAT breakdown », « 50,000-product catalog demo (target &lt; 100 ms) » (avant : « Caisse — démo moteur », « Panier », « TVA ventilée »…).</li><li><strong>Écran cuisine</strong> avec une alerte d&#39;imprimante cuisine reçue d&#39;une caisse (poste à imprimante injoignable) : bandeau « Printer … out of paper / unreachable (…) — n ticket(s) waiting at the register ».</li><li><strong>Alertes</strong> (manager connecté) : titres « Fraud alert: … », « Low stock: … », statut « To handle ».</li></ol></div>',3)])])}const E=t(S,[["render",q]]);export{w as __pageData,E as default};
